// src/autoscaler/tokenbucket.go - smoothing snippet:
func (tb *TokenBucket) applySmoothing(dt time.Duration) {
  decay := math.Exp(-float64(dt)/float64(tb.smoothWindow))
  tb.smoothedRate = tb.smoothedRate*decay + tb.instantRate*(1-decay)
}

